"""Raw SSE probe: print each line's arrival time (first 160 chars)."""
import os
import sys
import time

import httpx2

mode = sys.argv[1]  # off|on|tool|toolon
stream = (sys.argv[2] == "stream") if len(sys.argv) > 2 else True
prompt = sys.argv[3] if len(sys.argv) > 3 else "Name three German rivers with one sentence each."
body = {"model": "qwen3.8-flash-next", "temperature": 0.2,
        "messages": [{"role": "user", "content": prompt}],
        "chat_template_kwargs": {"enable_thinking": mode in ("on", "toolon")}, "stream": stream}
if stream:
    body["stream_options"] = {"include_usage": True}
if mode.startswith("tool"):
    body["tools"] = [{"type": "function", "function": {
        "name": "answer", "description": "Give the result",
        "parameters": {"type": "object", "properties": {
            "rivers": {"type": "array", "items": {"type": "string"}}, "note": {"type": "string"}},
            "required": ["rivers", "note"]}}}]
    body["tool_choice"] = "required"
t0 = time.monotonic()
with httpx2.Client(timeout=300) as c:
    with c.stream("POST", os.environ["QWEN_BASE_URL"].rstrip("/") + "/chat/completions",
                  headers={"Authorization": "Bearer " + os.environ["QWEN_API_KEY"]}, json=body) as r:
        print(f"{time.monotonic()-t0:6.2f} headers {r.status_code} {r.headers.get('content-type')}")
        for raw in r.iter_raw():
            for line in raw.split(b"\n"):
                if line:
                    print(f"{time.monotonic()-t0:6.2f} {line[:200]!r}", flush=True)

